from pathlib import Path
import zipfile, hashlib, json
root = Path(__file__).resolve().parent.parent
# D-054 (v0.5.0): the Source ZIP holds the source, docs and evidence needed to rebuild and audit this
# version. Browser screenshots (docs/*/screenshots, regenerated by the suites) and earlier releases'
# standalone HTML (kept in git history, their tags and GitHub Releases) are left out so the ZIP stays
# under GitHub's 100 MB file limit now that painted hubs make every screenshot ~2 MB.
def packaged(p):
    rel=p.relative_to(root).parts
    if any(part in {'.git','node_modules','test-output','__pycache__'} for part in rel) or p.suffix=='.zip' or 'SHA256SUMS' in p.name: return False
    if len(rel)>=3 and rel[0]=='docs' and rel[2]=='screenshots': return False
    # D-066 (v0.6.1): the built HTML (index.html and this release's standalone) is left out too — `npm run build`
    # regenerates both byte-identically and the standalone ships as its own release asset (ZIP 90 MB -> ~54 MB).
    if rel==('index.html',) or (rel[0]=='releases' and p.suffix=='.html'): return False
    return True
version = json.loads((root / 'package.json').read_text())['version']
release = root / 'releases'
source = release / f'Ashen_Crown_v{version}_Source.zip'
files = [p for p in root.rglob('*') if p.is_file() and packaged(p)]
with zipfile.ZipFile(source, 'w', zipfile.ZIP_DEFLATED) as archive:
    for p in sorted(files):
        entry = zipfile.ZipInfo('ashen-crown/' + p.relative_to(root).as_posix(), (2026, 10, 14, 0, 0, 0))
        entry.compress_type = zipfile.ZIP_DEFLATED
        archive.writestr(entry, p.read_bytes())
manifest = {p.name: hashlib.sha256(p.read_bytes()).hexdigest() for p in [release / f'Ashen_Crown_v{version}.html', source, release / f'Ashen_Crown_v{version}_Test_Report.md']}
(release / f'Ashen_Crown_v{version}_SHA256SUMS').write_text(''.join(f'{digest}  {name}\n' for name,digest in manifest.items()))
(release / 'SHA256SUMS.json').write_text(json.dumps(manifest, indent=2) + '\n')
print(json.dumps({'source_files': len(files), 'zip_bytes': source.stat().st_size, 'sha256': manifest}, indent=2))
